(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  let wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  wx += Math.sin((x+y)*0.012+t*0.5)*8 + Math.cos((x-y)*0.01-t*0.4)*6;
  wy += Math.cos((x-y)*0.013-t*0.45)*7 + Math.sin((x+y)*0.009+t*0.55)*5;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+4)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*70, 0.085, 1.8],
    [200+Math.sin(t*0.38+6)*90, 230+Math.cos(t*0.58+3)*40, 0.095, 2.4]
  ];
  let aS=0, iS=0, cross=0;
  for(let j=0;j<src.length;j++){
    const [sX,sY,f,sp]=src[j];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a=Math.sin(d*f-t*sp), i2=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS+=a; iS+=i2;
    for(let k=j+1;k<src.length;k++){
      const [sX2,sY2,f2,sp2]=src[k];
      const d2=Math.sqrt((sx-sX2)**2+(sy-sY2)**2);
      cross+=Math.sin(d*f+t*sp)*Math.sin(d2*f2-t*sp2)*0.15;
    }
  }
  const n=src.length, act=aS/n, inh=iS/n, cr=cross/(n*(n-1)*0.5);
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const micro=(Math.sin(sx*0.19+t*1.7)*Math.sin(sy*0.17-t*1.3)+Math.sin((sx-sy)*0.13+t*2.2)*0.4)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
