  const react1=Math.tanh((act-inh*0.7+bg*0.3+spiral+spiral2+cr)*2.2);
  const react2=Math.tanh((inh-act*0.5+cross*0.8+ring+micro)*2.5);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const voronoi=()=>{
    let md=99;for(const[sX,sY]of src){const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);if(d<md)md=d;}return Math.sin(md*0.15)*0.2;
  };
  const blend=react1*0.45+react2*0.2+cell*0.15+voronoi()*0.1+micro*0.1, v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[12,42,88],[18,82,118],[24,128,138],
    [60,168,140],[140,195,120],[210,190,70],[220,150,55],
    [195,100,60],[155,55,70],[95,30,72],[40,18,58],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const pulse=0.85+Math.sin(t*0.8)*0.08+Math.sin(t*1.3)*0.04;
  const lum=pulse*(0.8+Math.abs(react1)*0.15+Math.abs(react2)*0.05);
  const edge=(Math.abs(react1)>0.65?1.12:1.0)*(Math.abs(react2)>0.6?1.06:1.0);
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge)|0
  ];
}
